- CommonJS (`require` / `module.exports`). package.json has no `type` field; never add one.
- One test file per function, `test/<functionName>.test.js`, using `const { test } = require('node:test');` and `const assert = require('node:assert/strict');`. Test names are full present-tense sentences.
- Red before green: test file first, run `npm test`, see it fail for the stated reason.
- Text args must be strings; non-string throws `TypeError` whose message starts with the function name and a colon. Out-of-range numeric args throw `RangeError` with same prefix. Tests assert on error class and message prefix, never full message.
- No state: no mutation of args, no caching, no env reads.
- One commit per task, `feat:` prefix, imperative, test + implementation in same commit. Never commit while `npm test` is red.
- No task edits the tests of an earlier task or rewrites earlier code: each only appends a function and widens the export line.
- No runtime or dev dependencies.
- USER DECISION (overrides plan's test listings): the plan's PASSAGE constant in each test file must be used by a real test asserting the hand-count described in the task prose; and every Behaviour bullet in the task must have at least one test. Plan's fixed test counts (8/16/24/32) are not binding. The implementation code in the plan remains the code to write unless a new test exposes a bug.
// A word is a run of letters or digits (any script), optionally joined to the
// next run by a single apostrophe (straight or typographic) or hyphen. The
// joiners are only part of a word when letters or digits sit on both sides, so
// a trailing "well-" or "dogs'" loses its joiner. Everything else, including
// em dashes, periods and underscores, separates words.
const WORD_PATTERN = /[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu;

function assertText(fn, value) {
  if (typeof value !== 'string') {
    throw new TypeError(`${fn}: text must be a string, received ${value === null ? 'null' : typeof value}`);
  }
}

// Private: the single definition of "word" shared by every statistic below.
function tokenize(text) {
  return text.match(WORD_PATTERN) ?? [];
}

/**
 * Count the words in a piece of text.
 *
 * @param {string} text
 * @returns {number}
 */
function wordCount(text) {
  assertText('wordCount', text);
  return tokenize(text).length;
}

module.exports = { wordCount };
